-- PostgreSQL 17: instalação inicial em banco vazio. Execute com psql -v ON_ERROR_STOP=1.
CREATE SCHEMA "WEBFUSION";
SET search_path TO "WEBFUSION", pg_catalog;

CREATE TABLE IF NOT EXISTS "USERS" (
  "ID_USER" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "NA_USER_NAME" varchar(255) DEFAULT NULL,
  "NA_USER_EMAIL" varchar(320) NOT NULL,
  "NA_JOB_TITLE" varchar(255) DEFAULT NULL,
  "NA_DEPARTMENT" varchar(255) DEFAULT NULL,
  "NA_LOCATION" varchar(255) DEFAULT NULL,
  "NA_URL_PROFILE_IMG" varchar(2048) DEFAULT NULL,
  "DT_CREATED_AT" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "DT_UPDATED_AT" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("ID_USER")
);
CREATE UNIQUE INDEX users_uq_users_user_email ON "USERS" ("NA_USER_EMAIL");

CREATE TABLE IF NOT EXISTS "USER_ROLES" (
  "ID_USER" bigint NOT NULL,
  "NA_ROLE" varchar(9) CHECK ("NA_ROLE" IN ('admin', 'developer')) NOT NULL,
  "IS_ACTIVE" smallint NOT NULL DEFAULT 1,
  "DT_CREATED_AT" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "DT_UPDATED_AT" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("ID_USER", "NA_ROLE"),
  CONSTRAINT "FK_USER_ROLES_USER" FOREIGN KEY ("ID_USER")
    REFERENCES "USERS" ("ID_USER") ON DELETE CASCADE
);
CREATE INDEX user_roles_ix_user_roles_role_active ON "USER_ROLES" ("NA_ROLE", "IS_ACTIVE");

CREATE FUNCTION set_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW IS DISTINCT FROM OLD AND NEW."DT_UPDATED_AT" IS NOT DISTINCT FROM OLD."DT_UPDATED_AT" THEN
    NEW."DT_UPDATED_AT" := CURRENT_TIMESTAMP;
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER set_updated_at BEFORE UPDATE ON "USERS" FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER set_updated_at BEFORE UPDATE ON "USER_ROLES" FOR EACH ROW EXECUTE FUNCTION set_updated_at();
